input.sparql:
SELECT ?lighting_power_uri ?building_power_uri
WHERE {
  ?lighting_power_uri rdf:type brick:Electric_Power_Sensor ;
                      rdfs:label ?label ;
                      brick:hasTag brick:lighting .
  FILTER (CONTAINS(?label, 'zone'))
  ?building_power_uri rdf:type brick:Electric_Power_Sensor ;
                      rdfs:label ?global_label .
  FILTER (CONTAINS(?global_label, 'building'))
}
